/**
 * 对话框承载：同一份表单正文放进 `Dialog`（dialog.md「模式：对话框页脚」）。
 * - 表单状态放在 `DialogContent` 里面的组件中，关闭后随之卸载；不写 `{open ? <Body/> : null}`。
 * - 正文把 `dirty`、`pending` 上报给外框，外框用 `useUnsavedCloseGuard` 守住关闭。
 * - 提交中：确认与取消都禁用，Esc、点遮罩、关闭图标都关不掉。
 * - 失败：`FormError` 留在对话框里；成功：`toast.success` 后直接关闭，不经过守卫。
 */
import { useEffect, useId, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { FormError } from "@/components/ui/form-error";
import { UnsavedChangesDialog, useUnsavedCloseGuard } from "@/components/ui/unsaved-changes-dialog";
import {
  EMPTY_SERVICE,
  SERVICE_LABELS,
  SERVICE_VALIDATORS,
  ServiceFormBody,
  type ServiceValues,
} from "./service-form";
import { type SubmitResult, useFormState } from "./use-form-state";

type FormStatus = { dirty: boolean; pending: boolean };

const CLEAN: FormStatus = { dirty: false, pending: false };

export function NewServiceDialog({
  open,
  onOpenChange,
  submit,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  submit: (values: ServiceValues) => Promise<SubmitResult>;
}) {
  const [status, setStatus] = useState<FormStatus>(CLEAN);
  const guard = useUnsavedCloseGuard({
    dirty: status.dirty,
    pending: status.pending,
    onClose: () => onOpenChange(false),
  });

  return (
    <Dialog open={open} onOpenChange={guard.handleOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>新建服务</DialogTitle>
          <DialogDescription>创建后可以在服务详情里修改名称和通知设置。</DialogDescription>
        </DialogHeader>
        <NewServiceDialogBody
          submit={submit}
          onStatusChange={setStatus}
          onDone={() => onOpenChange(false)}
        />
        <UnsavedChangesDialog {...guard.dialogProps} />
      </DialogContent>
    </Dialog>
  );
}

function NewServiceDialogBody({
  submit,
  onStatusChange,
  onDone,
}: {
  submit: (values: ServiceValues) => Promise<SubmitResult>;
  onStatusChange: (status: FormStatus) => void;
  onDone: () => void;
}) {
  const form = useFormState({
    initialValues: EMPTY_SERVICE,
    validators: SERVICE_VALIDATORS,
    labels: SERVICE_LABELS,
    submit,
    onSaved: (values) => {
      toast.success(`已创建服务「${values.name}」`);
      onDone();
    },
  });
  const id = useId();
  const submitLabelId = `${id}-submit-label`;
  const blockedId = `${id}-blocked`;

  useEffect(() => {
    onStatusChange({ dirty: form.dirty, pending: form.isPending });
  }, [form.dirty, form.isPending, onStatusChange]);
  useEffect(() => () => onStatusChange(CLEAN), [onStatusChange]);

  return (
    <form ref={form.formRef} onSubmit={form.handleSubmit} noValidate className="grid gap-4">
      <ServiceFormBody
        values={form.values}
        onChange={form.onChange}
        errors={form.errors}
        disabled={form.isPending}
      />
      <FormError message={form.error} />
      <p
        id={blockedId}
        hidden={form.blockedReason === null}
        className="text-destructive-subtle-foreground text-xs"
      >
        {form.blockedReason}
      </p>
      <DialogFooter>
        <DialogClose render={<Button variant="outline" />} disabled={form.isPending}>
          取消
        </DialogClose>
        <Button
          type="submit"
          disabled={form.isPending}
          focusableWhenDisabled
          aria-labelledby={submitLabelId}
          aria-describedby={blockedId}
        >
          <span id={submitLabelId}>{form.isPending ? "创建中…" : "创建"}</span>
        </Button>
      </DialogFooter>
    </form>
  );
}

/**
 * 整页承载（缺省）：页头、表单正文、FormError、页脚。
 * - 提交中：提交按钮「创建中…」+ `disabled` + `focusableWhenDisabled`，字段禁用；「取消」仍可点。
 * - 失败：`FormError` 留在页脚按钮上方，不弹 toast。
 * - 成功：`toast.success`，基线换成已存值，然后跳到 `doneHref`。
 * - 离开：有未保存修改时，站内跳转与「取消」弹 `UnsavedChangesDialog`（ADR 0015）。
 * 链接都是宿主解析好的字符串（ADR 0005）。
 */
import { useId } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { FormError } from "@/components/ui/form-error";
import { useLinkAdapter } from "../app-shell/link-adapter";
import { usePageLeaveGuard } from "./page-leave-guard";
import {
  EMPTY_SERVICE,
  SERVICE_LABELS,
  SERVICE_VALIDATORS,
  ServiceFormBody,
  type ServiceValues,
} from "./service-form";
import { type SubmitResult, useFormState } from "./use-form-state";

export function NewServicePage({
  submit,
  cancelHref,
  doneHref,
}: {
  submit: (values: ServiceValues) => Promise<SubmitResult>;
  /** 「取消」去哪。 */
  cancelHref: string;
  /** 创建成功后去哪，通常是新对象的详情页。 */
  doneHref: string;
}) {
  const { navigate } = useLinkAdapter();
  const form = useFormState({
    initialValues: EMPTY_SERVICE,
    validators: SERVICE_VALIDATORS,
    labels: SERVICE_LABELS,
    submit,
    onSaved: (values) => {
      toast.success(`已创建服务「${values.name}」`);
      navigate(doneHref);
    },
  });
  const { leave, guard } = usePageLeaveGuard(form.dirty);
  const id = useId();
  const submitLabelId = `${id}-submit-label`;
  const blockedId = `${id}-blocked`;

  return (
    <div className="mx-auto flex w-full max-w-2xl flex-col gap-6 p-6">
      <header className="flex flex-col gap-1">
        <h1 className="font-semibold text-lg">新建服务</h1>
        <p className="text-muted-foreground text-xs">创建后可以在服务详情里修改名称和通知设置。</p>
      </header>
      <form
        ref={form.formRef}
        onSubmit={form.handleSubmit}
        noValidate
        className="flex flex-col gap-6"
      >
        <ServiceFormBody
          values={form.values}
          onChange={form.onChange}
          errors={form.errors}
          disabled={form.isPending}
        />
        <FormError message={form.error} />
        <div className="flex flex-wrap items-center justify-end gap-2">
          <p
            id={blockedId}
            hidden={form.blockedReason === null}
            className="mr-auto text-destructive-subtle-foreground text-xs"
          >
            {form.blockedReason}
          </p>
          <Button type="button" variant="secondary" onClick={() => leave(cancelHref)}>
            取消
          </Button>
          <Button
            type="submit"
            disabled={form.isPending}
            focusableWhenDisabled
            aria-labelledby={submitLabelId}
            aria-describedby={blockedId}
          >
            <span id={submitLabelId}>{form.isPending ? "创建中…" : "创建"}</span>
          </Button>
        </div>
      </form>
      {guard}
    </div>
  );
}

/**
 * 整页表单的离开拦截（ADR 0015）。不 import 任何路由库，只读链接适配。
 *
 * - 适配对象有 `useNavigationBlocker`：站内跳转（链接、命令式跳转、浏览器后退）被拦下，弹 `UnsavedChangesDialog`。
 * - 没有：退化为 `beforeunload` 加取消按钮守卫，并在开发态 `console.error` 一次。
 * - 两种情况都挂 `beforeunload`，拦刷新和关标签页。
 * - `navigateAway(href)`：先置「跳过下一次拦截」的标记，再跳转；跳转一次后标记必定清除。危险动作成功后跳走用它（#33）。
 *
 * 拦截能力是 hook，不能可选调用（#49）：有这一项时渲染 `NavigationBlockerDialog`，由它调用；没有时不渲染。
 */
import { type ReactNode, useEffect, useEffectEvent, useState } from "react";

import { UnsavedChangesDialog } from "@/components/ui/unsaved-changes-dialog";
import { type NavigationBlocker, useLinkAdapter } from "../app-shell/link-adapter";
import { createDevReporter, IS_DEV } from "../app-shell/shell-contracts";
import {
  armSkip,
  type LeaveSkip,
  leaveDecision,
  MISSING_BLOCKER_PROBLEM,
  runSkip,
  shouldBlockLeave,
} from "./page-leave";

const report = createDevReporter({
  enabled: IS_DEV,
  log: (message) => console.error(message),
  scope: "form-page",
});

function useBeforeUnload(dirty: boolean) {
  useEffect(() => {
    if (!dirty) return;
    const onBeforeUnload = (event: BeforeUnloadEvent) => event.preventDefault();
    window.addEventListener("beforeunload", onBeforeUnload);
    return () => window.removeEventListener("beforeunload", onBeforeUnload);
  }, [dirty]);
}

function NavigationBlockerDialog({
  dirty,
  useNavigationBlocker,
}: {
  dirty: boolean;
  useNavigationBlocker: (shouldBlock: boolean) => NavigationBlocker;
}) {
  const blocker = useNavigationBlocker(dirty);
  return (
    <UnsavedChangesDialog
      open={blocker.blocked}
      onConfirm={blocker.proceed}
      onCancel={blocker.reset}
    />
  );
}

/**
 * 返回 `leave(href)` 给「取消」这类离开入口，返回 `guard` 渲染在页面里（必须在调用本 hook 的组件之内渲染）。
 * 提交成功后的跳转直接用 `navigate`：那时基线已更新，拦截已解除。
 * 还有未保存修改却必须跳走时（危险动作成功后），用 `navigateAway(href)`：先置标记解除拦截，再跳转。
 */
export function usePageLeaveGuard(dirty: boolean): {
  leave: (href: string) => void;
  navigateAway: (href: string) => void;
  guard: ReactNode;
} {
  const { navigate, useNavigationBlocker } = useLinkAdapter();
  const [confirmHref, setConfirmHref] = useState<string | null>(null);
  const [skip, setSkip] = useState<LeaveSkip | null>(null);
  const hasBlocker = useNavigationBlocker !== undefined;
  const blocking = shouldBlockLeave(dirty, skip);

  useBeforeUnload(blocking);
  useEffect(() => {
    if (!hasBlocker) report([MISSING_BLOCKER_PROBLEM]);
  }, [hasBlocker]);

  // 标记生效、拦截按 blocking=false 解除之后才跳转。guard 里的拦截是子组件，它的 effect 先于本 effect 运行。
  // 跳转一次后标记必定清除：目标还是本页、跳转失败时，本页的拦截照常恢复。
  const navigateTo = useEffectEvent((href: string) => navigate(href));
  useEffect(() => {
    if (skip !== null)
      runSkip(
        skip,
        (href) => navigateTo(href),
        () => setSkip(null),
      );
  }, [skip]);

  const leave = (href: string) => {
    if (leaveDecision(dirty, hasBlocker) === "confirm") setConfirmHref(href);
    else navigate(href);
  };

  const navigateAway = (href: string) => {
    const next = armSkip(dirty, href);
    if (next === null) navigate(href);
    else setSkip(next);
  };

  const guard = (
    <>
      {useNavigationBlocker ? (
        <NavigationBlockerDialog dirty={blocking} useNavigationBlocker={useNavigationBlocker} />
      ) : null}
      <UnsavedChangesDialog
        open={confirmHref !== null}
        onConfirm={() => {
          setConfirmHref(null);
          if (confirmHref !== null) navigate(confirmHref);
        }}
        onCancel={() => setConfirmHref(null)}
      />
    </>
  );

  return { leave, navigateAway, guard };
}

/**
 * 整页离开拦截的纯逻辑（ADR 0015）。不 import React 与任何路由库。
 */

export const MISSING_BLOCKER_MESSAGE =
  "链接适配没有提供 useNavigationBlocker：表单页的站内跳转不受保护，只有刷新和关标签页会被 beforeunload 拦下（ADR 0015）。请在适配对象里实现 useNavigationBlocker。";

/**
 * 点「取消」这类站内离开时怎么做：
 * - `"navigate"`：直接跳转。没改过，或适配对象的 useNavigationBlocker 会拦下并弹确认框。
 * - `"confirm"`：改过且没有拦截能力，由离开入口自己弹确认框（取消按钮守卫）。
 */
export function leaveDecision(dirty: boolean, hasBlocker: boolean): "navigate" | "confirm" {
  return dirty && !hasBlocker ? "confirm" : "navigate";
}

/** 交给 app-shell 的 `createDevReporter`：开发态 `console.error`，同一个 id 只报一次。降级而不是坏掉，按 ADR 0009 不抛错。 */
export const MISSING_BLOCKER_PROBLEM = {
  id: "navigation-blocker",
  message: MISSING_BLOCKER_MESSAGE,
} as const;

/**
 * 「跳过下一次拦截」的标记（#33 边角）：危险动作成功后要跳走，这次跳转不能被拦。
 * `href` 是要去哪。跳转一次后标记必定清除（`runSkip`），所以只跳过一次。
 */
export type LeaveSkip = { href: string };

/** `navigateAway(href)` 先置标记：没改过时不用置，返回 null，调用方直接跳转。 */
export function armSkip(dirty: boolean, href: string): LeaveSkip | null {
  return dirty ? { href } : null;
}

/**
 * 按标记跳转一次，然后清除标记。无论跳转成功还是抛错，无论目标是不是本页（只改查询参数、被重定向回来），
 * 都清除：之后本页的离开拦截与 beforeunload 照常生效。
 * 拦截在跳转调用之内同步判定（TanStack 的 `useBlocker` 如此），清除在下一次渲染才生效，所以这次跳转不被拦。
 */
export function runSkip(
  skip: LeaveSkip,
  navigate: (href: string) => void,
  clear: () => void,
): void {
  try {
    navigate(skip.href);
  } finally {
    clear();
  }
}

/** 交给 `useNavigationBlocker` 与 `beforeunload` 的值：改过且没有标记时才拦。 */
export function shouldBlockLeave(dirty: boolean, skip: LeaveSkip | null): boolean {
  return dirty && skip === null;
}

/**
 * 受控的表单正文：`values`／`onChange`／`errors`／`disabled`，不持有状态，也不渲染 `<form>`。
 * 整页、对话框、抽屉、设置块和详情的编辑态都放这一份正文，只换外面的承载。
 * 复制后把「服务」换成你的对象：改 `ServiceValues`、选项、校验器和字段。
 */
import { useId } from "react";

import { FieldGroup, FieldLegend, FieldSeparator, FieldSet } from "@/components/ui/field";
import {
  type FieldErrors,
  type FieldOption,
  RadioGroupField,
  required,
  SelectField,
  SwitchField,
  TextareaField,
  TextField,
  type Validators,
} from "@/components/ui/form-fields";

type Environment = "production" | "staging" | "development";
type AlertLevel = "all" | "critical" | "none";

export type ServiceValues = {
  name: string;
  slug: string;
  description: string;
  environment: Environment | null;
  alertLevel: AlertLevel;
  notify: boolean;
};

export const EMPTY_SERVICE: ServiceValues = {
  name: "",
  slug: "",
  description: "",
  environment: null,
  alertLevel: "critical",
  notify: true,
};

/** 字段名，用于「为什么不能提交」。顺序即字段在页面上的顺序。 */
export const SERVICE_LABELS: Record<keyof ServiceValues, string> = {
  name: "服务名称",
  slug: "服务标识",
  description: "说明",
  environment: "运行环境",
  alertLevel: "告警级别",
  notify: "接收通知",
};

export const SERVICE_VALIDATORS: Validators<ServiceValues> = {
  name: (value) => {
    if (value.trim() === "") return "请填写服务名称";
    return value.trim().length > 40 ? "服务名称不能超过 40 个字符" : null;
  },
  slug: (value) => {
    if (value === "") return "请填写服务标识";
    return /^[a-z][a-z0-9-]*$/.test(value) ? null : "只能用小写字母、数字和 -，并以字母开头";
  },
  environment: required("请选择运行环境"),
};

const ENVIRONMENT_OPTIONS: readonly FieldOption<Environment>[] = [
  { value: "production", label: "生产" },
  { value: "staging", label: "预发" },
  { value: "development", label: "开发" },
];

const ALERT_LEVEL_OPTIONS: readonly FieldOption<AlertLevel>[] = [
  { value: "all", label: "全部告警" },
  { value: "critical", label: "只有严重告警" },
  { value: "none", label: "不告警" },
];

export function ServiceFormBody({
  values,
  onChange,
  errors,
  disabled,
}: {
  values: ServiceValues;
  onChange: (values: ServiceValues) => void;
  errors: FieldErrors<ServiceValues>;
  disabled: boolean;
}) {
  const id = useId();
  return (
    <FieldGroup>
      <FieldSet>
        <FieldLegend>基本信息</FieldLegend>
        <FieldGroup>
          <TextField
            id={`${id}-name`}
            label={SERVICE_LABELS.name}
            required
            hint="最多 40 个字符，团队内可见"
            value={values.name}
            onValueChange={(name) => onChange({ ...values, name })}
            error={errors.name}
            disabled={disabled}
            autoComplete="off"
          />
          <TextField
            id={`${id}-slug`}
            label={SERVICE_LABELS.slug}
            required
            hint="用在地址和命令行里，创建后不能修改"
            value={values.slug}
            onValueChange={(slug) => onChange({ ...values, slug })}
            error={errors.slug}
            disabled={disabled}
            autoComplete="off"
          />
          <TextareaField
            id={`${id}-description`}
            label={SERVICE_LABELS.description}
            hint="选填"
            value={values.description}
            onValueChange={(description) => onChange({ ...values, description })}
            error={errors.description}
            disabled={disabled}
          />
        </FieldGroup>
      </FieldSet>
      <FieldSeparator />
      <FieldSet>
        <FieldLegend>运行</FieldLegend>
        <FieldGroup>
          <SelectField
            id={`${id}-environment`}
            label={SERVICE_LABELS.environment}
            required
            placeholder="选择运行环境"
            options={ENVIRONMENT_OPTIONS}
            value={values.environment}
            onValueChange={(environment) => onChange({ ...values, environment })}
            error={errors.environment}
            disabled={disabled}
          />
          <RadioGroupField
            id={`${id}-alert-level`}
            label={SERVICE_LABELS.alertLevel}
            options={ALERT_LEVEL_OPTIONS}
            value={values.alertLevel}
            onValueChange={(alertLevel) => onChange({ ...values, alertLevel })}
            error={errors.alertLevel}
            disabled={disabled}
          />
        </FieldGroup>
      </FieldSet>
      <FieldSeparator />
      <FieldSet>
        <FieldLegend>通知</FieldLegend>
        <FieldGroup>
          <SwitchField
            id={`${id}-notify`}
            label={SERVICE_LABELS.notify}
            hint="部署失败时给负责人发邮件"
            checked={values.notify}
            onCheckedChange={(notify) => onChange({ ...values, notify })}
            error={errors.notify}
            disabled={disabled}
          />
        </FieldGroup>
      </FieldSet>
    </FieldGroup>
  );
}

/**
 * 表单正文的状态（ADR 0014）：一个 `useState<TValues>` 单对象，加上基线、碰过的字段、是否提交过、
 * 提交中与提交失败。字段模型的纯函数来自 `form-fields`。整页、对话框、设置块共用这一份写法。
 */
import { type FormEvent, useEffect, useEffectEvent, useRef, useState } from "react";

import {
  blockedReason,
  type FieldErrors,
  hasErrors,
  isDirty,
  type TouchedFields,
  touchChanged,
  type Validators,
  validate,
  visibleErrors,
} from "@/components/ui/form-fields";

/** 提交函数的结果。失败时 `error` 是给用户看的中文消息，显示在页脚按钮上方的 `FormError` 里。 */
export type SubmitResult = { error: string | null };

export function useFormState<TValues extends object>({
  initialValues,
  validators,
  labels,
  submit,
  onSaved,
}: {
  initialValues: TValues;
  validators: Validators<TValues>;
  /** 字段名，用来写「为什么不能提交」。 */
  labels: Record<keyof TValues, string>;
  submit: (values: TValues) => Promise<SubmitResult>;
  /** 提交成功、基线已换成已存值之后调用：toast、关闭浮层或跳转放在这里。 */
  onSaved: (values: TValues) => void;
}) {
  const [values, setValues] = useState<TValues>(initialValues);
  const [baseline, setBaseline] = useState<TValues>(initialValues);
  const [touched, setTouched] = useState<TouchedFields<TValues>>({});
  const [submitted, setSubmitted] = useState(false);
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [saved, setSaved] = useState<{ values: TValues } | null>(null);
  const [focusRequest, setFocusRequest] = useState(0);
  const formRef = useRef<HTMLFormElement>(null);

  const allErrors = validate(values, validators);
  const errors: FieldErrors<TValues> = visibleErrors(allErrors, touched, submitted);

  // 成功后的回调放到下一次提交后的 effect 里：子组件里的离开拦截先按新基线解除，跳转才不会被拦。
  const notifySaved = useEffectEvent((next: TValues) => onSaved(next));
  useEffect(() => {
    if (saved !== null) notifySaved(saved.values);
  }, [saved]);

  // 提交时有错误：等错误渲染出来，再把焦点移到第一个出错的控件。
  useEffect(() => {
    if (focusRequest === 0) return;
    formRef.current?.querySelector<HTMLElement>('[aria-invalid="true"]')?.focus();
  }, [focusRequest]);

  const onChange = (next: TValues) => {
    setTouched((current) => touchChanged(current, values, next));
    setValues(next);
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isPending) return;
    setSubmitted(true);
    if (hasErrors(allErrors)) {
      setFocusRequest((count) => count + 1);
      return;
    }
    setIsPending(true);
    setError(null);
    let result: SubmitResult;
    try {
      result = await submit(values);
    } catch {
      result = { error: "提交失败，请重试。" };
    }
    setIsPending(false);
    if (result.error !== null) {
      setError(result.error);
      return;
    }
    setBaseline(values);
    setSaved({ values });
  };

  return {
    values,
    onChange,
    errors,
    dirty: isDirty(values, baseline),
    isPending,
    error,
    /** 提交过且有错误时的说明；提交按钮的 `aria-describedby` 指向显示它的元素。 */
    blockedReason: submitted ? blockedReason(allErrors, labels) : null,
    formRef,
    handleSubmit,
  };
}
